/bin/bash -lc "cat > /tmp/review_cases.py <<'PY'
import json, math
p='/work/cases.json'
d=json.load(open(p))
d['cases']=[c for c in d['cases'] if c['name']"'!='"'indirect recursion even when unused']
for c in d['cases']:
 if c['name']=='missing procedure ending':
  c['source']='to p'; c['expect']['error']={'line':1}
d['cases'].extend([
 {'name':'procedure ending must stand alone','mode':'2d','source':'to p\\nfd 1\\nend fd 2','expect':{'segments':[],'error':{'line':3}}},
 {'name':'definition must start a line','mode':'2d','source':'fd 1 to p','expect':{'segments':[],'error':{'line':1}}},
 {'name':'procedure call requires numeric arguments','mode':'2d','source':'to p ma: x\\nfd x\\nend\\np nope','expect':{'segments':[],'error':{'line':4,'column':3}}},
 {'name':'active frame depth 32 with a call accepted','mode':'2d','source':'to p\\n'+'repeat 1 ['*31+'fd 1'+']'*31+'\\nend\\np','expect':{'segments':[{'from':[0,0,0],'to':[0,1,0],'color':'#16866a','width':3}]}},
 {'name':'x coordinate limit preserves earlier segments','mode':'2d','source':'rt 90 fd 100000\\nfd 1','expect':{'segments':[{'from':[0,0,0],'to':[100000,0,0],'color':'#16866a','width':3}],'error':{'line':2}}},
])
assert d['version']==1
assert len({c['name'] for c in d['cases']})==len(d['cases'])
for c in d['cases']:
 assert c['mode'] in ('2d','3d') and isinstance(c['source'],str)
 ex=c['expect']; assert ex and set(ex)<= {'segments','error'}
 if 'error' in ex:
  assert 1<=ex['error']['line']<=len(c['source'].split('\\n'))
  if 'column' in ex['error']:
   assert 1<=ex['error']['column']<=len(c['source'].split('\\n')[ex['error']['line']-1])+1
 for s in ex.get('segments',[]):
  assert set(s)=={'from','to','color','width'}
  assert 1<=s['width']<=12 and s['width']==int(s['width'])
  assert len(s['color'])==7 and s['color']==s['color'].lower()
  for pt in [s['from'],s['to']]:assert len(pt)==3 and all(math.isfinite(v) for v in pt)
with open(p,'w') as f:json.dump(d,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\\n')
print('Validated',len(d['cases']),'independent cases; JSON, unique names, segment schema, finite coordinates, and error positions checked.')
